// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _am) public {
        vm.assume(_am <= type(uint256).max);
        // Drive a Collect call
        (bool ok, ) = address(c).call{value: _am}(abi.encodeWithSelector(c.Collect.selector, _am));
        // The rule: MinSum must always be 1 ether
        assertTrue(c.MinSum() == 1 ether);
    }
}

